callGraph.callee:
fields_def
        .into_iter()
        .map(|(key, hint)| {
            let value = file
                .as_ref()
                .and_then(|f| f.get(key, profile.as_deref()))
                .unwrap_or_default();
            ConfigField {
                key: key.to_string(),
                value,
                hint,
                env_override: env_override(key, profile.as_deref()),
            }
        }).collect

app
        .config_fields
        .iter()
        .enumerate()
        .map(|(i, f)| {
            let display = f.key.strip_prefix("VB_").unwrap_or(&f.key);
            let row_style = if i == app.selected_config {
                selection_style(theme)
            } else if theme.no_color {
                Style::default()
            } else {
                Style::default().fg(theme.text_dim)
            };
            ListItem::new(Line::from(Span::styled(format!(" {display}"), row_style)))
        }).collect

app
        .jobs
        .iter()
        .enumerate()
        .map(|(i, j)| {
            let icon = job_icon(j, app.spinner_frame);
            let color = job_color(j.status, theme);
            let icon_style = if theme.no_color {
                Style::default()
            } else {
                Style::default().fg(color)
            };
            let row_style = if i == app.selected_job {
                selection_style(theme)
            } else if theme.no_color {
                Style::default()
            } else {
                Style::default().fg(theme.text_dim)
            };
            ListItem::new(Line::from(vec![
                Span::styled(format!(" {icon} "), icon_style),
                Span::styled(j.id.clone(), row_style),
            ]))
        }).collect

state.lines[start..end]
            .iter()
            .map(|l| {
                let color = if theme.no_color {
                    theme.text
                } else if l.contains("[SKILL]") {
                    theme.primary
                } else if l.contains("error") || l.contains("Error") {
                    theme.error
                } else {
                    theme.text_dim
                };
                let style = if theme.no_color {
                    Style::default()
                } else {
                    Style::default().fg(color)
                };
                Line::from(Span::styled(l.as_str().to_string(), style))
            }).collect

app
        .sessions
        .iter()
        .enumerate()
        .map(|(i, s)| {
            let icon_style = if theme.no_color {
                Style::default()
            } else {
                Style::default().fg(theme.success)
            };
            let row_style = if i == app.selected_session {
                selection_style(theme)
            } else if theme.no_color {
                Style::default()
            } else {
                Style::default().fg(theme.text_dim)
            };
            ListItem::new(Line::from(vec![
                Span::styled(" ● ", icon_style),
                Span::styled(s.id.clone(), row_style),
            ]))
        }).collect
